#!/usr/bin/env bash

# group-eval-configure.sh — point this worktree's pg_net kick at group-eval.
#
#   ./supabase/scripts/group-eval-configure.sh            # the in-network Kong route (default)
#   ./supabase/scripts/group-eval-configure.sh <url>      # any other URL
#   ./supabase/scripts/group-eval-configure.sh --unset    # no kick; the queue waits
#
# The URL lives in Vault (`group_eval_url`, set through
# app_public.group_eval_set_url); the kick secret is generated by the migration.
# Inside the stack's Docker network, Kong answers as `kong:8000`, so the default
# is the same for every worktree. Contract: docs/specs/tech/groups-contract.md §2.10.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck disable=SC1091
source "${SCRIPT_DIR}/_common.sh"

DEFAULT_URL="http://kong:8000/functions/v1/group-eval"

url="${1:-${DEFAULT_URL}}"
[[ "${url}" == "--unset" ]] && url=""

container="$(resolve_db_container)" || exit 1
docker exec -i "${container}" psql -U postgres -d postgres -v ON_ERROR_STOP=1 -Atq -v url="${url}" >/dev/null <<'SQL'
select app_public.group_eval_set_url(:'url');
SQL

if [[ -n "${url}" ]]; then
  echo "[supabase] group-eval kick URL: ${url}"
else
  echo "[supabase] group-eval kick URL unset (the queue waits for a drain)"
fi
